SELECT AVG(team1_score) AS average_score
FROM (
    SELECT match_id, SUM(runs_scored + extra_runs) AS team1_score
    FROM Deliveries
    WHERE inning = 1
      AND match_id IN (
          SELECT match_id FROM Matches WHERE city = 'Ahmedabad'
      )
    GROUP BY match_id
) AS first_inning_scores;

